//#region src/lib/geminiReceipt.ts
/**
* Envía un comprobante de pago en imagen (base64 o data URL) al servidor
* para extraer código de evento, monto, fecha y estado de la transferencia.
*/
async function analyzePaymentReceipt(imageDataUrl, expectedEventCode, expectedAmountARS) {
	const response = await fetch("/api/gemini/analyze-receipt", {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({
			imageDataUrl,
			expectedEventCode,
			expectedAmountARS
		})
	});
	const payload = await response.json().catch(() => ({}));
	if (!response.ok) {
		const errorMessage = typeof payload?.error === "string" && payload.error ? payload.error : `Error ${response.status} al analizar el comprobante en el servidor.`;
		throw new Error(errorMessage);
	}
	return payload;
}
